'AC-meta.delivery.1'; from __future__ import annotations; import json; from pathlib import Path; REPO = Path(__file__).resolve().parents[2]; BASELINE_PATH = REPO / 'common/meta/data/delivery-layer-baseline.json'; DELIVERY_DIRS = ('apps/backend/src/routers', 'apps/backend/src/schemas'); TOLERANCE_LINES = 50
def _delivery_census() -> dict[str, dict[str, int]]:
    census: dict[str, dict[str, int]] = {}
    for rel in DELIVERY_DIRS:
        files = 0; lines = 0
        for py in sorted((REPO / rel).rglob('*.py')):
            if '__pycache__' in py.parts: continue
            files += 1; lines += len(py.read_text(encoding='utf-8').splitlines())
        census[rel] = {'files': files, 'lines': lines}
    return census
def test_AC_meta_delivery_1_census_is_nonvacuous() -> None: census = _delivery_census(); routers = census['apps/backend/src/routers']; schemas = census['apps/backend/src/schemas']; assert routers['files'] >= 20 and routers['lines'] > 0, f'sentinel missing: expected >= 20 non-empty *.py files under apps/backend/src/routers, saw {routers}; the census is scanning the wrong root (did routers/ move?)'; assert schemas['files'] >= 10 and schemas['lines'] > 0, f'sentinel missing: expected >= 10 non-empty *.py files under apps/backend/src/schemas, saw {schemas}; the census is scanning the wrong root (did schemas/ move?)'
def test_AC_meta_delivery_1_delivery_layer_only_thins() -> None: baseline: dict[str, int] = json.loads(BASELINE_PATH.read_text(encoding='utf-8')); census = {rel: c['lines'] for rel, c in _delivery_census().items()}; grown = {rel: (baseline.get(rel, 0), lines) for rel, lines in census.items() if lines > baseline.get(rel, 0) + TOLERANCE_LINES}; assert not grown, f"the app delivery layer grew — routers/ and schemas/ are sanctioned for routing and DTO glue only (AC-meta.delivery.1; migration-standard.md 'The app delivery layer') and their bulk may only shrink as packages absorb logic. Move domain behavior into the owning package's base/extension instead. If this growth is genuine delivery glue (a new endpoint's routing/DTO surface), raise common/meta/data/delivery-layer-baseline.json in this same PR so the choice is visible in review.\ngrown (baseline, actual): {grown}\nfull census: {json.dumps(census, indent=2)}"; stale = {rel: (expected, census.get(rel, 0)) for rel, expected in baseline.items() if census.get(rel, 0) < expected - TOLERANCE_LINES}; assert not stale, f'the baseline over-counts — the delivery layer thinned (good!); lower common/meta/data/delivery-layer-baseline.json to the new census in the same PR so the ratchet stays tight and the burndown is visible.\nstale (baseline, actual): {stale}\nfull census: {json.dumps(census, indent=2)}'
